   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      config.currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      config.currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[config.currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...config.dataFeedback, selection: config.dataFeedback.results[config.currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (config.currentFocus >= list.length) config.currentFocus = 0;
    if (config.currentFocus < 0) config.currentFocus = list.length - 1;
    // Add "active" class to the item
    list[config.currentFocus].setAttribute("aria-selected", "true");
    list[config.currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (config.currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[config.currentFocus].click();
      }
    }
  };

  const navigate = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  if (!config.resultsList.navigation && !config._navigationListenerAttached) {
    config.inputField.addEventListener("keydown", navigate);
    config._navigationListenerAttached = true;
  }
};"
    }
  ],
  "expected_accessibility_effect": "Keyboard navigation will correctly track focus and active descendant across list re-renders, ensuring that pressing Enter selects the currently highlighted suggestion.",
  "functional_risks": [
    "If a custom navigation function is provided, it will not benefit from the shared state on config; it must manage its own focus tracking.",
    "The config object now has additional properties (currentFocus, dataFeedback, _navigationListenerAttached) which could theoretically clash with other code, but this is unlikely given the limited scope."
  ],
  "verification_requirements": [
    "After typing 'b', pressing ArrowDown twice, typing 'l', pressing ArrowDown once, and pressing Enter, the input value must be 'Blackberry'.",
    "Repeatedly opening and closing the suggestion list must not accumulate multiple keydown listeners.",
    "If a custom navigation function is supplied via config.resultsList.navigation, it should continue to work as expected."
  ]
}

